function formatDateGmt7(date) {
    const gmt7 = new Date(date.getTime() + 7 * 60 * 60 * 1000);
    const yyyy = gmt7.getFullYear();
    const mm = String(gmt7.getMonth() + 1).padStart(2, '0');
    const dd = String(gmt7.getDate()).padStart(2, '0');
    const hh = String(gmt7.getHours()).padStart(2, '0');
    const mi = String(gmt7.getMinutes()).padStart(2, '0');
    const ss = String(gmt7.getSeconds()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd} ${hh}:${mi}:${ss}`;
}

const scannedTime = formatDateGmt7(new Date());
const env = "LOCAL";  // Bạn có thể thay đổi hoặc lấy từ biến môi trường nếu cần
let message = "";

const allPassed = $json["allPassed"];
const failedCases = $json["failedCases"] || [];

if (allPassed || failedCases.length === 0) {
  message += "*✅ SUCCESS ✅ ALL TESTCASES PASSED*\n";
  message += `*▪️Environment*: ${env}\n`;
  message += `*▪️Scanned Time (GMT+7)*: ${scannedTime}\n`;
} else {
  message += "*❌ ERROR ❌ SOME TESTCASES FAILED*\n";
  message += `*▪️Environment*: ${env}\n`;
  message += `*▪️Scanned Time (GMT+7)*: ${scannedTime}\n`;
  message += failedCases
    .map(tc => `\n      Code: ${tc.code} | Result: ${tc.result}`)
    .join("\n");
}

return [
  {
    json: {
      message: message
    }
  }
];

const output = $json["stdout"];
const lines = output.split('\n').filter(line => line.includes("Code=") && line.includes("Result="));

let failedCases = [];
let allPassed = true;

lines.forEach(line => {
  const match = line.match(/Code=(\S+), Result=(\S+)/);
  if (match) {
    const code = match[1];
    const result = match[2].toUpperCase();
    if (result !== "PASSED") {
      allPassed = false;
      failedCases.push({ code, result });
    }
  }
});

return [
  {
    json: {
      allPassed,
      failedCases,
      rawOutput: output
    }
  }
];
